String sObjClass = myStepPage.getString("pxObjClass");
Database db = tools.getDatabase();
ClassDefinition cdClass = db.getClassDef(sObjClass);

if(cdClass != null){
	List<String> lKeys = cdClass.getKeyPropertyList();
	String sKey = lKeys.get(0);
	if(myStepPage.getString(sKey).equals("")){
		String sGUID = pega_rulesengine_utilities.pxGetNewGUID();
		myStepPage.putString(sKey, sGUID);
	}
}

String strMessage = tools.getActivityStatus().getWorstMessage();
if (!tools.getPrimaryPage().hasMessages()){
tools.getPrimaryPage().addMessage("pySaveFailed\t" + strMessage);
}

// If the save failed and this is a new record, we want to keep thinking
// it is a new record by removing the pxUpdateOperator.
// If it is not a new record, then so what?  The pxUpdateOperator will be set
ClipboardProperty updateOperator = tools.getPrimaryPage().getProperty(".pxUpdateOperator");
updateOperator.setValue("");
